[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>GlobalStone — Global Commercial Real Estate Services</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:wght@400;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="shared.css">
<style>
/* ===== HOMEPAGE SPECIFIC ===== */

/* HERO */
.hero {
  position: relative;
  height: 620px;
  background: linear-gradient(135deg, #003F2D 0%, #012A2D 50%, #0A1628 100%);
  display: flex;
  align-items: center;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; inset: 0;
  background: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?w=1600&q=80') center/cover no-repeat;
  opacity: 0.18;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 760px;
  padding: 0 40px;
}
.hero-eyebrow {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 20px;
}
.hero-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(36px, 5vw, 58px);
  font-weight: 700;
  color: #fff;
  line-height: 1.15;
  margin-bottom: 24px;
}
.hero-subtitle {
  font-size: 18px;
  color: rgba(255,255,255,0.8);
  line-height: 1.6;
  margin-bottom: 36px;
  max-width: 580px;
}
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--gold);
  color: #0A1628;
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.5px;
  padding: 15px 32px;
  border: none;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.2s, transform 0.2s;
}
.btn-primary:hover { background: #d4a017; transform: translateY(-1px); }
.btn-outline {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: transparent;
  color: #fff;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.5px;
  padding: 13px 28px;
  border: 1.5px solid rgba(255,255,255,0.5);
  text-decoration: none;
  transition: border-color 0.2s, background 0.2s;
}
.btn-outline:hover { border-color: #fff; background: rgba(255,255,255,0.08); }

/* FEATURED INSIGHTS */
.featured-insights { background: #fff; padding: 72px 0; }
.section-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 36px;
}
.insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.insight-card {
  border: 1px solid var(--border);
  overflow: hidden;
  transition: box-shadow 0.2s;
}
.insight-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.10); }
.insight-card-img {
  height: 200px;
  background: linear-gradient(135deg, #003F2D, #012A2D);
  position: relative;
  overflow: hidden;
}
.insight-card-img img {
  width: 100%; height: 100%;
  object-fit: cover;
  opacity: 0.7;
}
.insight-card-body { padding: 24px; }
.insight-tag {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 10px;
}
.insight-card-body h3 {
  font-size: 17px;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: 16px;
}
.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--primary);
  text-decoration: none;
  letter-spacing: 0.3px;
}
.link-arrow::after { content: '→'; transition: transform 0.2s; }
.link-arrow:hover::after { transform: translateX(4px); }

/* ANNOUNCEMENT BANNER */
.announcement-banner {
  background: var(--primary);
  padding: 20px 0;
}
.banner-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.banner-text {
  font-size: 16px;
  font-weight: 600;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 12px;
}
.banner-text::before {
  content: '●';
  color: var(--gold);
  font-size: 10px;
}
.btn-banner {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  color: var(--gold);
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 1px;
  text-transform: uppercase;
  text-decoration: none;
  border: 1.5px solid var(--gold);
  padding: 9px 20px;
  transition: background 0.2s, color 0.2s;
  white-space: nowrap;
}
.btn-banner:hover { background: var(--gold); color: #0A1628; }

/* ABOUT STATEMENT */
.about-statement { padding: 96px 0; background: #f7f8f9; }
.about-inner {
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 80px;
  align-items: center;
}
.about-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(30px, 3.5vw, 42px);
  font-weight: 700;
  color: var(--navy);
  line-height: 1.3;
  margin-bottom: 28px;
}
.about-body { font-size: 17px; color: var(--muted); line-height: 1.75; margin-bottom: 36px; }
.about-stats {
  display: flex;
  flex-direction: column;
  gap: 32px;
}
.stat-item { border-left: 3px solid var(--gold); padding-left: 20px; }
.stat-number {
  font-family: 'Playfair Display', serif;
  font-size: 42px;
  font-weight: 700;
  color: var(--primary);
  line-height: 1;
  margin-bottom: 6px;
}
.stat-label { font-size: 14px; color: var(--muted); font-weight: 500; }

/* WHAT WE DO */
.what-we-do { padding: 96px 0; background: #fff; }
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(28px, 3vw, 40px);
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 16px;
}
.section-subtitle { font-size: 17px; color: var(--muted); margin-bottom: 56px; max-width: 580px; }
.tabs-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 0;
  border: 1px solid var(--border);
}
.tabs-nav { background: #f7f8f9; border-right: 1px solid var(--border); }
.tab-btn {
  display: block;
  width: 100%;
  padding: 28px 32px;
  background: none;
  border: none;
  border-bottom: 1px solid var(--border);
  text-align: left;
  cursor: pointer;
  transition: background 0.18s;
  position: relative;
}
.tab-btn:last-child { border-bottom: none; }
.tab-btn.active { background: #fff; }
.tab-btn.active::after {
  content: '';
  position: absolute;
  right: -1px; top: 0; bottom: 0;
  width: 3px;
  background: var(--gold);
}
.tab-btn-label {
  font-size: 15px;
  font-weight: 600;
  color: var(--muted);
  transition: color 0.18s;
}
.tab-btn.active .tab-btn-label { color: var(--navy); }
.tab-btn:hover .tab-btn-label { color: var(--navy); }
.tabs-panel { padding: 52px 56px; }
.tab-content { display: none; }
.tab-content.active { display: block; animation: fadeIn 0.25s ease; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.tab-eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 20px;
}
.tab-title {
  font-family: 'Playfair Display', serif;
  font-size: 30px;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 20px;
  line-height: 1.3;
}
.tab-body { font-size: 16px; color: var(--muted); line-height: 1.75; margin-bottom: 36px; }
.tab-list { list-style: none; padding: 0; margin-bottom: 40px; }
.tab-list li {
  padding: 10px 0;
  font-size: 15px;
  color: var(--navy);
  font-weight: 500;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 10px;
}
.tab-list li::before { content: '›'; color: var(--gold); font-size: 18px; font-weight: 700; }

/* NEWSLETTER */
.newsletter { padding: 80px 0; background: var(--navy); }
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 60px;
}
.newsletter-title {
  font-family: 'Playfair Display', serif;
  font-size: 32px;
  font-weight: 700;
  color: #fff;
  margin-bottom: 12px;
}
.newsletter-subtitle { font-size: 16px; color: rgba(255,255,255,0.7); }
.newsletter-form { display: flex; gap: 0; }
.newsletter-input {
  padding: 15px 24px;
  font-size: 15px;
  border: none;
  background: rgba(255,255,255,0.12);
  color: #fff;
  width: 280px;
  outline: none;
}
.newsletter-input::placeholder { color: rgba(255,255,255,0.5); }
.newsletter-input:focus { background: rgba(255,255,255,0.18); }
.btn-gold {
  background: var(--gold);
  color: #0A1628;
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.5px;
  padding: 15px 28px;
  border: none;
  cursor: pointer;
  transition: background 0.2s;
}
.btn-gold:hover { background: #d4a017; }

/* LATEST INSIGHTS */
.latest-insights { padding: 96px 0; background: #fff; }
.latest-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  margin-top: 48px;
}
.latest-card { border: 1px solid var(--border); overflow: hidden; transition: box-shadow 0.2s; }
.latest-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.10); }
.latest-card-img {
  height: 180px;
  background: linear-gradient(135deg, #003F2D 0%, #012A2D 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.latest-card-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.65; }
.latest-card-body { padding: 24px; }
.latest-cat { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 10px; }
.latest-card-body h3 { font-size: 16px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 12px; }
.latest-date { font-size: 13px; color: var(--muted); }

/* COMMITMENT */
.commitment { padding: 96px 0; background: #f7f8f9; }
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 56px;
}
.commitment-card {
  background: #fff;
  padding: 40px 32px;
  border-top: 4px solid var(--primary);
  transition: box-shadow 0.2s, transform 0.2s;
}
.commitment-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.10); transform: translateY(-4px); }
.commitment-icon {
  width: 48px; height: 48px;
  background: var(--primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  font-size: 20px;
  color: #fff;
}
.commitment-card h3 { font-size: 18px; font-weight: 700; color: var(--navy); margin-bottom: 14px; }
.commitment-card p { font-size: 14px; color: var(--muted); line-height: 1.7; margin-bottom: 24px; }

/* RESPONSIVE */
@media (max-width: 1024px) {
  .about-inner { grid-template-columns: 1fr; gap: 48px; }
  .about-stats { flex-direction: row; flex-wrap: wrap; gap: 24px; }
  .stat-item { flex: 1; min-width: 120px; }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .newsletter-inner { grid-template-columns: 1fr; gap: 32px; }
}
@media (max-width: 768px) {
  .hero { height: auto; padding: 80px 0 60px; }
  .insights-grid { grid-template-columns: 1fr; }
  .latest-grid { grid-template-columns: 1fr; }
  .commitment-grid { grid-template-columns: 1fr 1fr; }
  .tabs-layout { grid-template-columns: 1fr; }
  .tabs-nav { display: flex; overflow-x: auto; border-right: none; border-bottom: 1px solid var(--border); }
  .tab-btn { border-bottom: none; border-right: 1px solid var(--border); white-space: nowrap; flex-shrink: 0; }
  .tab-btn.active::after { right: 0; top: auto; bottom: -1px; left: 0; width: auto; height: 3px; }
  .tabs-panel { padding: 32px 24px; }
  .newsletter-form { flex-direction: column; }
  .newsletter-input { width: 100%; }
}
@media (max-width: 480px) {
  .commitment-grid { grid-template-columns: 1fr; }
}
</style>
</head>
