/* ===== GLOBALSTONE — SHARED STYLES ===== */

:root {
  --primary: #003F2D;
  --secondary: #012A2D;
  --navy: #0A1628;
  --gold: #C9A84C;
  --light: #E6E6E6;
  --border: #e2e4e8;
  --muted: #5a6474;
  --bg-light: #f7f8f9;
  --white: #ffffff;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--navy);
  background: #fff;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font-family: inherit; }

.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 40px;
}

/* ===== HEADER ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--navy);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  transition: box-shadow 0.3s;
}
.site-header.scrolled {
  box-shadow: 0 4px 24px rgba(0,0,0,0.25);
}
.header-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 0;
}

/* LOGO */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
  margin-right: 40px;
}
.logo-mark {
  width: 36px; height: 36px;
  background: var(--gold);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 13px;
  color: #0A1628;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}
.logo-text {
  font-size: 18px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.3px;
}

/* MAIN NAV */
.main-nav { flex: 1; }
.nav-list { display: flex; align-items: center; height: 72px; gap: 0; }
.nav-item { position: relative; height: 100%; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 100%;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 500;
  color: rgba(255,255,255,0.85);
  text-decoration: none;
  background: none;
  border: none;
  cursor: pointer;
  transition: color 0.18s;
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active { color: #fff; }
.nav-item.has-mega .nav-link:hover { color: var(--gold); }
.nav-chevron { font-size: 12px; transition: transform 0.2s; }
.nav-item.has-mega.open .nav-chevron { transform: rotate(180deg); }

/* HEADER ACTIONS */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-left: 20px;
  flex-shrink: 0;
}
.btn-header-search {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px; height: 36px;
  color: rgba(255,255,255,0.7);
  transition: color 0.18s;
}
.btn-header-search:hover { color: #fff; }
.btn-contact {
  padding: 8px 20px;
  background: var(--gold);
  color: #0A1628;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.3px;
  border-radius: 2px;
  transition: background 0.18s;
}
.btn-contact:hover { background: #d4a017; }

/* HAMBURGER */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 36px; height: 36px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  margin-left: 12px;
}
.hamburger span {
  display: block;
  height: 2px;
  background: rgba(255,255,255,0.85);
  border-radius: 1px;
  transition: all 0.25s;
}
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* MEGA MENU */
.mega-menu {
  position: absolute;
  top: 72px;
  left: 50%;
  transform: translateX(-50%);
  width: 860px;
  background: #fff;
  border-top: 3px solid var(--gold);
  box-shadow: 0 16px 48px rgba(0,0,0,0.18);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.2s, visibility 0.2s, transform 0.2s;
  transform: translateX(-50%) translateY(-8px);
  z-index: 999;
}
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}
.mega-inner {
  display: grid;
  grid-template-columns: 1fr 1fr 240px;
  gap: 0;
  padding: 40px;
}
.mega-col { padding: 0 24px; }
.mega-col:first-child { padding-left: 0; }
.mega-col.mega-featured { border-left: 1px solid var(--border); }
.mega-heading {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}
.mega-list { list-style: none; }
.mega-list li { margin-bottom: 2px; }
.mega-list a {
  display: block;
  padding: 8px 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--navy);
  transition: color 0.15s, padding-left 0.15s;
}
.mega-list a:hover { color: var(--primary); padding-left: 6px; }
.mega-feature-card { margin-top: 8px; }
.mega-feature-img {
  height: 100px;
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  border-radius: 2px;
  margin-bottom: 14px;
}
.mega-feature-tag { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 6px; }
.mega-feature-title { font-size: 13px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 14px; }

/* MOBILE MENU */
.mobile-menu {
  display: none;
  background: var(--navy);
  border-top: 1px solid rgba(255,255,255,0.08);
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.mobile-menu.open {
  max-height: 600px;
  overflow-y: auto;
}
.mobile-nav-list { padding: 16px 0 24px; }
.mobile-nav-item { border-bottom: 1px solid rgba(255,255,255,0.06); }
.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 40px;
  font-size: 15px;
  font-weight: 500;
  color: rgba(255,255,255,0.9);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: color 0.18s;
}
.mobile-nav-link:hover { color: var(--gold); }
.accordion-icon { font-size: 20px; color: var(--gold); transition: transform 0.25s; }
.mobile-nav-item.open .accordion-icon { transform: rotate(45deg); }
.accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}
.accordion-panel.open { max-height: 600px; }
.accordion-sub {
  padding: 8px 40px 20px 56px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.accordion-sub-heading {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--gold);
  margin: 12px 0 8px;
}
.accordion-sub a {
  font-size: 14px;
  color: rgba(255,255,255,0.75);
  padding: 6px 0;
  transition: color 0.15s;
}
.accordion-sub a:hover { color: #fff; }

/* ===== PAGE HERO (non-home pages) ===== */
.page-hero {
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 50%, var(--navy) 100%);
  padding: 80px 0 72px;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute; inset: 0;
  background: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?w=1600&q=60') center/cover;
  opacity: 0.1;
}
.page-hero-content { position: relative; z-index: 2; max-width: 760px; }
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  margin-bottom: 20px;
}
.breadcrumb a { color: rgba(255,255,255,0.6); }
.breadcrumb a:hover { color: rgba(255,255,255,0.9); }
.breadcrumb-sep { font-size: 10px; }
.page-hero-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: var(--gold); margin-bottom: 16px; }
.page-hero-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(32px, 4vw, 52px);
  font-weight: 700;
  color: #fff;
  line-height: 1.2;
  margin-bottom: 20px;
}
.page-hero-desc { font-size: 17px; color: rgba(255,255,255,0.8); line-height: 1.65; max-width: 600px; }

/* ===== INTRO STATEMENT ===== */
.intro-statement {
  padding: 72px 0;
  background: #fff;
  border-bottom: 1px solid var(--border);
}
.intro-inner {
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 80px;
  align-items: center;
}
.intro-text h2 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(26px, 2.5vw, 36px);
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 18px;
  line-height: 1.3;
}
.intro-text p { font-size: 16px; color: var(--muted); line-height: 1.75; }
.intro-stat-stack { display: flex; flex-direction: column; gap: 24px; }
.intro-stat { border-left: 3px solid var(--gold); padding-left: 20px; }
.intro-stat-num { font-family: 'Playfair Display', serif; font-size: 36px; font-weight: 700; color: var(--primary); line-height: 1; margin-bottom: 4px; }
.intro-stat-label { font-size: 13px; color: var(--muted); font-weight: 500; }

/* ===== CAPABILITIES GRID ===== */
.capabilities-section { padding: 80px 0; background: var(--bg-light); }
.cap-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.cap-card {
  background: #fff;
  padding: 36px 28px;
  border: 1px solid var(--border);
  border-top: 3px solid var(--primary);
  transition: box-shadow 0.2s, transform 0.2s;
}
.cap-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.09); transform: translateY(-3px); }
.cap-icon {
  width: 44px; height: 44px;
  background: rgba(0,63,45,0.1);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 18px;
}
.cap-card h3 { font-size: 17px; font-weight: 700; color: var(--navy); margin-bottom: 12px; line-height: 1.3; }
.cap-card p { font-size: 14px; color: var(--muted); line-height: 1.7; margin-bottom: 20px; }

/* ===== RELATED SERVICES ===== */
.related-services { padding: 72px 0; background: #fff; }
.related-services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.related-card {
  border: 1px solid var(--border);
  padding: 32px;
  transition: box-shadow 0.2s;
}
.related-card:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.08); }
.related-card h3 { font-size: 16px; font-weight: 700; color: var(--navy); margin-bottom: 10px; }
.related-card p { font-size: 14px; color: var(--muted); line-height: 1.65; margin-bottom: 20px; }

/* ===== TESTIMONIAL ===== */
.testimonial-section { padding: 80px 0; background: var(--navy); }
.testimonial-inner { max-width: 760px; margin: 0 auto; text-align: center; }
.testimonial-quote {
