/* ===== GLOBALSTONE — SHARED STYLES ===== */

:root {
  --primary: #003F2D;
  --secondary: #012A2D;
  --navy: #0A1628;
  --gold: #C9A84C;
  --light: #E6E6E6;
  --border: #e2e4e8;
  --muted: #5a6474;
  --bg-light: #f7f8f9;
  --white: #ffffff;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--navy);
  background: #fff;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font-family: inherit; }

.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 40px;
}

/* ===== HEADER ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--navy);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  transition: box-shadow 0.3s;
}
.site-header.scrolled {
  box-shadow: 0 4px 24px rgba(0,0,0,0.25);
}
.header-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 0;
}

/* LOGO */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
  margin-right: 40px;
}
.logo-mark {
  width: 36px; height: 36px;
  background: var(--gold);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 13px;
  color: #0A1628;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}
.logo-text {
  font-size: 18px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.3px;
}

/* MAIN NAV */
.main-nav { flex: 1; }
.nav-list { display: flex; align-items: center; height: 72px; gap: 0; }
.nav-item { position: relative; height: 100%; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 100%;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 500;
  color: rgba(255,255,255,0.85);
  text-decoration: none;
  background: none;
  border: none;
  cursor: pointer;
  transition: color 0.18s;
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active { color: #fff; }
.nav-item.has-mega .nav-link:hover { color: var(--gold); }
.nav-chevron { font-size: 12px; transition: transform 0.2s; }
.nav-item.has-mega.open .nav-chevron { transform: rotate(180deg); }

/* HEADER ACTIONS */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-left: 20px;
  flex-shrink: 0;
}
.btn-header-search {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px; height: 36px;
  color: rgba(255,255,255,0.7);
  transition: color 0.18s;
}
.btn-header-search:hover { color: #fff; }
.btn-contact {
  padding: 8px 20px;
  background: var(--gold);
  color: #0A1628;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.3px;
  border-radius: 2px;
  transition: background 0.18s;
}
.btn-contact:hover { background: #d4a017; }

/* HAMBURGER */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 36px; height: 36px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  margin-left: 12px;
}
.hamburger span {
  display: block;
  height: 2px;
  background: rgba(255,255,255,0.85);
  border-radius: 1px;
  transition: all 0.25s;
}
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* MEGA MENU */
.mega-menu {
  position: absolute;
  top: 72px;
  left: 50%;
  transform: translateX(-50%);
  width: 860px;
  background: #fff;
  border-top: 3px solid var(--gold);
  box-shadow: 0 16px 48px rgba(0,0,0,0.18);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.2s, visibility 0.2s, transform 0.2s;
  transform: translateX(-50%) translateY(-8px);
  z-index: 999;
}
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}
.mega-inner {
  display: grid;
  grid-template-columns: 1fr 1fr 240px;
  gap: 0;
  padding: 40px;
}
.mega-col { padding: 0 24px; }
.mega-col:first-child { padding-left: 0; }
.mega-col.mega-featured { border-left: 1px solid var(--border); }
.mega-heading {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}
.mega-list { list-style: none; }
.mega-list li { margin-bottom: 2px; }
.mega-list a {
  display: block;
  padding: 8px 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--navy);
  transition: color 0.15s, padding-left 0.15s;
}
.mega-list a:hover { color: var(--primary); padding-left: 6px; }
.mega-feature-card { margin-top: 8px; }
.mega-feature-img {
  height: 100px;
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  border-radius: 2px;
  margin-bottom: 14px;
}
.mega-feature-tag { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 6px; }
.mega-feature-title { font-size: 13px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 14px; }

/* MOBILE MENU */
.mobile-menu {
  display: none;
  background: var(--navy);
  border-top: 1px solid rgba(255,255,255,0.08);
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.mobile-menu.open {
  max-height: 600px;
  overflow-y: auto;
}
.mobile-nav-list { padding: 16px 0 24px; }
.mobile-nav-item { border-bottom: 1px solid rgba(255,255,255,0.06); }
.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 40px;
  font-size: 15px;
  font-weight: 500;
  color: rgba(255,255,255,0.9);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: color 0.18s;
}
.mobile-nav-link:hover { color: var(--gold); }
.accordion-icon { font-size: 20px; color: var(--gold); transition: transform 0.25s; }
.mobile-nav-item.open .accordion-icon { transform: rotate(45deg); }
.accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}
.accordion-panel.open { max-height: 600px; }
.accordion-sub {
  padding: 8px 40px 20px 56px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.accordion-sub-heading {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--gold);
  margin: 12px 0 8px;
}
.accordion-sub a {
  font-size: 14px;
  color: rgba(255,255,255,0.75);
  padding: 6px 0;
  transition: color 0.15s;
}
.accordion-sub a:hover { color: #fff; }

/* ===== PAGE HERO (non-home pages) ===== */
.page-hero {
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 50%, var(--navy) 100%);
  padding: 80px 0 72px;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute; inset: 0;
  background: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?w=1600&q=60') center/cover;
  opacity: 0.1;
}
.page-hero-content { position: relative; z-index: 2; max-width: 760px; }
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  margin-bottom: 20px;
}
.breadcrumb a { color: rgba(255,255,255,0.6); }
.breadcrumb a:hover { color: rgba(255,255,255,0.9); }
.breadcrumb-sep { font-size: 10px; }
.page-hero-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: var(--gold); margin-bottom: 16px; }
.page-hero-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(32px, 4vw, 52px);
  font-weight: 700;
  color: #fff;
  line-height: 1.2;
  margin-bottom: 20px;
}
.page-hero-desc { font-size: 17px; color: rgba(255,255,255,0.8); line-height: 1.65; max-width: 600px; }

/* ===== INTRO STATEMENT ===== */
.intro-statement {
  padding: 72px 0;
  background: #fff;
  border-bottom: 1px solid var(--border);
}
.intro-inner {
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 80px;
  align-items: center;
}
.intro-text h2 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(26px, 2.5vw, 36px);
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 18px;
  line-height: 1.3;
}
.intro-text p { font-size: 16px; color: var(--muted); line-height: 1.75; }
.intro-stat-stack { display: flex; flex-direction: column; gap: 24px; }
.intro-stat { border-left: 3px solid var(--gold); padding-left: 20px; }
.intro-stat-num { font-family: 'Playfair Display', serif; font-size: 36px; font-weight: 700; color: var(--primary); line-height: 1; margin-bottom: 4px; }
.intro-stat-label { font-size: 13px; color: var(--muted); font-weight: 500; }

/* ===== CAPABILITIES GRID ===== */
.capabilities-section { padding: 80px 0; background: var(--bg-light); }
.cap-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.cap-card {
  background: #fff;
  padding: 36px 28px;
  border: 1px solid var(--border);
  border-top: 3px solid var(--primary);
  transition: box-shadow 0.2s, transform 0.2s;
}
.cap-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.09); transform: translateY(-3px); }
.cap-icon {
  width: 44px; height: 44px;
  background: rgba(0,63,45,0.1);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 18px;
}
.cap-card h3 { font-size: 17px; font-weight: 700; color: var(--navy); margin-bottom: 12px; line-height: 1.3; }
.cap-card p { font-size: 14px; color: var(--muted); line-height: 1.7; margin-bottom: 20px; }

/* ===== RELATED SERVICES ===== */
.related-services { padding: 72px 0; background: #fff; }
.related-services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.related-card {
  border: 1px solid var(--border);
  padding: 32px;
  transition: box-shadow 0.2s;
}
.related-card:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.08); }
.related-card h3 { font-size: 16px; font-weight: 700; color: var(--navy); margin-bottom: 10px; }
.related-card p { font-size: 14px; color: var(--muted); line-height: 1.65; margin-bottom: 20px; }

/* ===== TESTIMONIAL ===== */
.testimonial-section { padding: 80px 0; background: var(--navy); }
.testimonial-inner { max-width: 760px; margin: 0 auto; text-align: center; }
.testimonial-quote {
  font-family: 'Playfair Display', serif;
  font-size: clamp(22px, 2.5vw, 30px);
  font-weight: 400;
  color: #fff;
  line-height: 1.55;
  margin-bottom: 32px;
  font-style: italic;
}
.testimonial-quote::before { content: '"'; }
.testimonial-quote::after { content: '"'; }
.testimonial-author { font-size: 14px; font-weight: 600; color: var(--gold); letter-spacing: 0.5px; margin-bottom: 4px; }
.testimonial-role { font-size: 13px; color: rgba(255,255,255,0.6); }

/* ===== CTA SECTION ===== */
.cta-section { padding: 80px 0; background: var(--primary); }
.cta-inner { text-align: center; }
.cta-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(28px, 3vw, 40px);
  font-weight: 700;
  color: #fff;
  margin-bottom: 16px;
}
.cta-subtitle { font-size: 17px; color: rgba(255,255,255,0.8); margin-bottom: 36px; }
.btn-cta-white {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff;
  color: var(--primary);
  font-weight: 700;
  font-size: 15px;
  padding: 15px 36px;
  border: none;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.2s, transform 0.2s;
}
.btn-cta-white:hover { background: #f0f0f0; transform: translateY(-2px); }

/* ===== FEATURED TOPICS ===== */
.featured-topics { padding: 72px 0; background: #fff; }
.topics-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 64px;
  align-items: start;
  margin-top: 40px;
}
.topics-list { border: 1px solid var(--border); }
.topic-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 28px;
  border-bottom: 1px solid var(--border);
  transition: background 0.15s;
  cursor: pointer;
}
.topic-item:last-child { border-bottom: none; }
.topic-item:hover { background: var(--bg-light); }
.topic-item h3 { font-size: 16px; font-weight: 600; color: var(--navy); }
.topic-item span { color: var(--gold); font-size: 20px; }
.insight-sidebar { display: flex; flex-direction: column; gap: 24px; }
.sidebar-card {
  border: 1px solid var(--border);
  overflow: hidden;
}
.sidebar-card-img { height: 140px; background: linear-gradient(135deg, var(--primary), var(--secondary)); overflow: hidden; }
.sidebar-card-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.7; }
.sidebar-card-body { padding: 20px; }
.sidebar-card-tag { font-size: 10px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 8px; }
.sidebar-card-body h3 { font-size: 14px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 12px; }

/* ===== RELATED INSIGHTS ===== */
.related-insights { padding: 72px 0; background: var(--bg-light); }
.ri-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.ri-card {
  background: #fff;
  border: 1px solid var(--border);
  overflow: hidden;
  transition: box-shadow 0.2s;
}
.ri-card:hover { box-shadow: 0 6px 24px rgba(0,0,0,0.09); }
.ri-card-img { height: 160px; background: linear-gradient(135deg, var(--primary), var(--secondary)); overflow: hidden; }
.ri-card-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.65; }
.ri-card-body { padding: 24px; }
.ri-tag { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 8px; }
.ri-card-body h3 { font-size: 15px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 14px; }
.ri-date { font-size: 12px; color: var(--muted); }

/* ===== PARTNERSHIP HIGHLIGHT ===== */
.partnership { padding: 80px 0; background: #fff; }
.partnership-inner {
  display: grid;
  grid-template-columns: 1fr 400px;
  gap: 72px;
  align-items: center;
}
.partnership-text h2 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(26px, 2.5vw, 36px);
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 20px;
  line-height: 1.3;
}
.partnership-text p { font-size: 16px; color: var(--muted); line-height: 1.75; margin-bottom: 24px; }
.partnership-metrics { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.p-metric { background: var(--bg-light); padding: 28px 24px; border-left: 3px solid var(--gold); }
.p-metric-num { font-family: 'Playfair Display', serif; font-size: 36px; font-weight: 700; color: var(--primary); line-height: 1; margin-bottom: 8px; }
.p-metric-label { font-size: 13px; color: var(--muted); line-height: 1.4; }

/* ===== FOOTER ===== */
.site-footer { background: var(--navy); padding: 72px 0 0; }
.footer-top {
  display: grid;
  grid-template-columns: 280px 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 56px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-tagline { font-size: 14px; color: rgba(255,255,255,0.55); line-height: 1.6; margin-bottom: 24px; max-width: 220px; }
.footer-social { display: flex; gap: 12px; }
.social-link {
  width: 36px; height: 36px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: rgba(255,255,255,0.7);
  transition: border-color 0.15s, color 0.15s;
}
.social-link:hover { border-color: var(--gold); color: var(--gold); }
.footer-nav-col h4 {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-nav-col ul { list-style: none; }
.footer-nav-col li { margin-bottom: 10px; }
.footer-nav-col a { font-size: 14px; color: rgba(255,255,255,0.65); transition: color 0.15s; }
.footer-nav-col a:hover { color: #fff; }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 24px 0;
  flex-wrap: wrap;
}
.footer-copy { font-size: 13px; color: rgba(255,255,255,0.4); }
.footer-legal { display: flex; gap: 24px; flex-wrap: wrap; }
.footer-legal a { font-size: 12px; color: rgba(255,255,255,0.4); transition: color 0.15s; }
.footer-legal a:hover { color: rgba(255,255,255,0.8); }

/* ===== SECTION HEADINGS ===== */
.section-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 16px;
}
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(28px, 3vw, 40px);
  font-weight: 700;
  color: var(--navy);
  line-height: 1.25;
  margin-bottom: 16px;
}
.section-subtitle { font-size: 17px; color: var(--muted); margin-bottom: 48px; max-width: 600px; line-height: 1.65; }

/* ===== LINK ARROW ===== */
.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--primary);
  text-decoration: none;
  letter-spacing: 0.3px;
}
.link-arrow::after { content: '→'; transition: transform 0.2s; }
.link-arrow:hover::after { transform: translateX(4px); }

/* ===== CAROUSEL ===== */
.carousel-container { position: relative; overflow: hidden; }
.carousel-track { display: flex; transition: transform 0.4s ease; }
.carousel-slide { flex: 0 0 100%; padding: 40px; background: #fff; border: 1px solid var(--border); }
.carousel-controls { display: flex; justify-content: center; gap: 12px; margin-top: 24px; }
.carousel-btn {
  width: 40px; height: 40px;
  border: 1.5px solid var(--border);
  background: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: var(--navy);
  transition: border-color 0.15s, background 0.15s;
}
.carousel-btn:hover { border-color: var(--primary); background: var(--primary); color: #fff; }

/* ===== PROPERTY TYPES CTA ===== */
.property-types-cta { padding: 72px 0; background: var(--bg-light); }
.property-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-top: 40px;
}
.property-tile {
  background: var(--navy);
  padding: 32px 20px;
  text-align: center;
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.property-tile:hover { background: var(--primary); transform: translateY(-4px); }
.property-tile-icon { font-size: 28px; }
.property-tile-label { font-size: 13px; font-weight: 600; color: #fff; letter-spacing: 0.5px; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .container { padding: 0 24px; }
  .cap-grid { grid-template-columns: repeat(2, 1fr); }
  .related-services-grid { grid-template-columns: repeat(2, 1fr); }
  .ri-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-top { grid-template-columns: 1fr 1fr; gap: 40px; }
  .intro-inner { grid-template-columns: 1fr; gap: 40px; }
  .partnership-inner { grid-template-columns: 1fr; gap: 48px; }
  .topics-layout { grid-template-columns: 1fr; }
  .property-grid { grid-template-columns: repeat(3, 1fr); }
  .mega-menu { width: 700px; }
}
@media (max-width: 768px) {
  .container { padding: 0 20px; }
  .main-nav { display: none; }
  .header-actions { display: none; }
  .hamburger { display: flex; }
  .mobile-menu { display: block; }
  .mega-menu { display: none; }
  .cap-grid { grid-template-columns: 1fr; }
  .related-services-grid { grid-template-columns: 1fr; }
  .ri-grid { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .partnership-metrics { grid-template-columns: 1fr; }
  .property-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .footer-top { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; gap: 16px; }
  .footer-legal { gap: 12px; }
  .property-grid { grid-template-columns: 1fr 1fr; }
}

/* ===== GLOBALSTONE — SHARED STYLES ===== */

:root {
  --primary: #003F2D;
  --secondary: #012A2D;
  --navy: #0A1628;
  --gold: #C9A84C;
  --light: #E6E6E6;
  --border: #e2e4e8;
  --muted: #5a6474;
  --bg-light: #f7f8f9;
  --white: #ffffff;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--navy);
  background: #fff;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font-family: inherit; }

.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 40px;
}

/* ===== HEADER ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--navy);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  transition: box-shadow 0.3s;
}
.site-header.scrolled {
  box-shadow: 0 4px 24px rgba(0,0,0,0.25);
}
.header-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 0;
}

/* LOGO */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
  margin-right: 40px;
}
.logo-mark {
  width: 36px; height: 36px;
  background: var(--gold);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 13px;
  color: #0A1628;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}
.logo-text {
  font-size: 18px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.3px;
}

/* MAIN NAV */
.main-nav { flex: 1; }
.nav-list { display: flex; align-items: center; height: 72px; gap: 0; }
.nav-item { position: relative; height: 100%; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 100%;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 500;
  color: rgba(255,255,255,0.85);
  text-decoration: none;
  background: none;
  border: none;
  cursor: pointer;
  transition: color 0.18s;
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active { color: #fff; }
.nav-item.has-mega .nav-link:hover { color: var(--gold); }
.nav-chevron { font-size: 12px; transition: transform 0.2s; }
.nav-item.has-mega.open .nav-chevron { transform: rotate(180deg); }

/* HEADER ACTIONS */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-left: 20px;
  flex-shrink: 0;
}
.btn-header-search {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px; height: 36px;
  color: rgba(255,255,255,0.7);
  transition: color 0.18s;
}
.btn-header-search:hover { color: #fff; }
.btn-contact {
  padding: 8px 20px;
  background: var(--gold);
  color: #0A1628;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.3px;
  border-radius: 2px;
  transition: background 0.18s;
}
.btn-contact:hover { background: #d4a017; }

/* HAMBURGER */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 36px; height: 36px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  margin-left: 12px;
}
.hamburger span {
  display: block;
  height: 2px;
  background: rgba(255,255,255,0.85);
  border-radius: 1px;
  transition: all 0.25s;
}
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* MEGA MENU */
.mega-menu {
  position: absolute;
  top: 72px;
  left: 50%;
  transform: translateX(-50%);
  width: 860px;
  background: #fff;
  border-top: 3px solid var(--gold);
  box-shadow: 0 16px 48px rgba(0,0,0,0.18);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.2s, visibility 0.2s, transform 0.2s;
  transform: translateX(-50%) translateY(-8px);
  z-index: 999;
}
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}
.mega-inner {
  display: grid;
  grid-template-columns: 1fr 1fr 240px;
  gap: 0;
  padding: 40px;
}
.mega-col { padding: 0 24px; }
.mega-col:first-child { padding-left: 0; }
.mega-col.mega-featured { border-left: 1px solid var(--border); }
.mega-heading {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}
.mega-list { list-style: none; }
.mega-list li { margin-bottom: 2px; }
.mega-list a {
  display: block;
  padding: 8px 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--navy);
  transition: color 0.15s, padding-left 0.15s;
}
.mega-list a:hover { color: var(--primary); padding-left: 6px; }
.mega-feature-card { margin-top: 8px; }
.mega-feature-img {
  height: 100px;
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  border-radius: 2px;
  margin-bottom: 14px;
}
.mega-feature-tag { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 6px; }
.mega-feature-title { font-size: 13px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 14px; }

/* MOBILE MENU */
.mobile-menu {
  display: none;
  background: var(--navy);
  border-top: 1px solid rgba(255,255,255,0.08);
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.mobile-menu.open {
  max-height: 600px;
  overflow-y: auto;
}
.mobile-nav-list { padding: 16px 0 24px; }
.mobile-nav-item { border-bottom: 1px solid rgba(255,255,255,0.06); }
.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 40px;
  font-size: 15px;
  font-weight: 500;
  color: rgba(255,255,255,0.9);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: color 0.18s;
}
.mobile-nav-link:hover { color: var(--gold); }
.accordion-icon { font-size: 20px; color: var(--gold); transition: transform 0.25s; }
.mobile-nav-item.open .accordion-icon { transform: rotate(45deg); }
.accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}
.accordion-panel.open { max-height: 600px; }
.accordion-sub {
  padding: 8px 40px 20px 56px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.accordion-sub-heading {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--gold);
  margin: 12px 0 8px;
}
.accordion-sub a {
  font-size: 14px;
  color: rgba(255,255,255,0.75);
  padding: 6px 0;
  transition: color 0.15s;
}
.accordion-sub a:hover { color: #fff; }

/* ===== PAGE HERO (non-home pages) ===== */
.page-hero {
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 50%, var(--navy) 100%);
  padding: 80px 0 72px;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute; inset: 0;
  background: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?w=1600&q=60') center/cover;
  opacity: 0.1;
}
.page-hero-content { position: relative; z-index: 2; max-width: 760px; }
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  margin-bottom: 20px;
}
.breadcrumb a { color: rgba(255,255,255,0.6); }
.breadcrumb a:hover { color: rgba(255,255,255,0.9); }
.breadcrumb-sep { font-size: 10px; }
.page-hero-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: var(--gold); margin-bottom: 16px; }
.page-hero-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(32px, 4vw, 52px);
  font-weight: 700;
  color: #fff;
  line-height: 1.2;
  margin-bottom: 20px;
}
.page-hero-desc { font-size: 17px; color: rgba(255,255,255,0.8); line-height: 1.65; max-width: 600px; }

/* ===== INTRO STATEMENT ===== */
.intro-statement {
  padding: 72px 0;
  background: #fff;
  border-bottom: 1px solid var(--border);
}
.intro-inner {
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 80px;
  align-items: center;
}
.intro-text h2 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(26px, 2.5vw, 36px);
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 18px;
  line-height: 1.3;
}
.intro-text p { font-size: 16px; color: var(--muted); line-height: 1.75; }
.intro-stat-stack { display: flex; flex-direction: column; gap: 24px; }
.intro-stat { border-left: 3px solid var(--gold); padding-left: 20px; }
.intro-stat-num { font-family: 'Playfair Display', serif; font-size: 36px; font-weight: 700; color: var(--primary); line-height: 1; margin-bottom: 4px; }
.intro-stat-label { font-size: 13px; color: var(--muted); font-weight: 500; }

/* ===== CAPABILITIES GRID ===== */
.capabilities-section { padding: 80px 0; background: var(--bg-light); }
.cap-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.cap-card {
  background: #fff;
  padding: 36px 28px;
  border: 1px solid var(--border);
  border-top: 3px solid var(--primary);
  transition: box-shadow 0.2s, transform 0.2s;
}
.cap-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.09); transform: translateY(-3px); }
.cap-icon {
  width: 44px; height: 44px;
  background: rgba(0,63,45,0.1);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 18px;
}
.cap-card h3 { font-size: 17px; font-weight: 700; color: var(--navy); margin-bottom: 12px; line-height: 1.3; }
.cap-card p { font-size: 14px; color: var(--muted); line-height: 1.7; margin-bottom: 20px; }

/* ===== RELATED SERVICES ===== */
.related-services { padding: 72px 0; background: #fff; }
.related-services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.related-card {
  border: 1px solid var(--border);
  padding: 32px;
  transition: box-shadow 0.2s;
}
.related-card:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.08); }
.related-card h3 { font-size: 16px; font-weight: 700; color: var(--navy); margin-bottom: 10px; }
.related-card p { font-size: 14px; color: var(--muted); line-height: 1.65; margin-bottom: 20px; }

/* ===== TESTIMONIAL ===== */
.testimonial-section { padding: 80px 0; background: var(--navy); }
.testimonial-inner { max-width: 760px; margin: 0 auto; text-align: center; }
.testimonial-quote {
  font-family: 'Playfair Display', serif;
  font-size: clamp(22px, 2.5vw, 30px);
  font-weight: 400;
  color: #fff;
  line-height: 1.55;
  margin-bottom: 32px;
  font-style: italic;
}
.testimonial-quote::before { content: '"'; }
.testimonial-quote::after { content: '"'; }
.testimonial-author { font-size: 14px; font-weight: 600; color: var(--gold); letter-spacing: 0.5px; margin-bottom: 4px; }
.testimonial-role { font-size: 13px; color: rgba(255,255,255,0.6); }

/* ===== CTA SECTION ===== */
.cta-section { padding: 80px 0; background: var(--primary); }
.cta-inner { text-align: center; }
.cta-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(28px, 3vw, 40px);
  font-weight: 700;
  color: #fff;
  margin-bottom: 16px;
}
.cta-subtitle { font-size: 17px; color: rgba(255,255,255,0.8); margin-bottom: 36px; }
.btn-cta-white {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff;
  color: var(--primary);
  font-weight: 700;
  font-size: 15px;
  padding: 15px 36px;
  border: none;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.2s, transform 0.2s;
}
.btn-cta-white:hover { background: #f0f0f0; transform: translateY(-2px); }

/* ===== FEATURED TOPICS ===== */
.featured-topics { padding: 72px 0; background: #fff; }
.topics-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 64px;
  align-items: start;
  margin-top: 40px;
}
.topics-list { border: 1px solid var(--border); }
.topic-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 28px;
  border-bottom: 1px solid var(--border);
  transition: background 0.15s;
  cursor: pointer;
}
.topic-item:last-child { border-bottom: none; }
.topic-item:hover { background: var(--bg-light); }
.topic-item h3 { font-size: 16px; font-weight: 600; color: var(--navy); }
.topic-item span { color: var(--gold); font-size: 20px; }
.insight-sidebar { display: flex; flex-direction: column; gap: 24px; }
.sidebar-card {
  border: 1px solid var(--border);
  overflow: hidden;
}
.sidebar-card-img { height: 140px; background: linear-gradient(135deg, var(--primary), var(--secondary)); overflow: hidden; }
.sidebar-card-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.7; }
.sidebar-card-body { padding: 20px; }
.sidebar-card-tag { font-size: 10px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 8px; }
.sidebar-card-body h3 { font-size: 14px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 12px; }

/* ===== RELATED INSIGHTS ===== */
.related-insights { padding: 72px 0; background: var(--bg-light); }
.ri-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.ri-card {
  background: #fff;
  border: 1px solid var(--border);
  overflow: hidden;
  transition: box-shadow 0.2s;
}
.ri-card:hover { box-shadow: 0 6px 24px rgba(0,0,0,0.09); }
.ri-card-img { height: 160px; background: linear-gradient(135deg, var(--primary), var(--secondary)); overflow: hidden; }
.ri-card-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.65; }
.ri-card-body { padding: 24px; }
.ri-tag { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 8px; }
.ri-card-body h3 { font-size: 15px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 14px; }
.ri-date { font-size: 12px; color: var(--muted); }

/* ===== PARTNERSHIP HIGHLIGHT ===== */
.partnership { padding: 80px 0; background: #fff; }
.partnership-inner {
  display: grid;
  grid-template-columns: 1fr 400px;
  gap: 72px;
  align-items: center;
}
.partnership-text h2 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(26px, 2.5vw, 36px);
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 20px;
  line-height: 1.3;
}
.partnership-text p { font-size: 16px; color: var(--muted); line-height: 1.75; margin-bottom: 24px; }
.partnership-metrics { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.p-metric { background: var(--bg-light); padding: 28px 24px; border-left: 3px solid var(--gold); }
.p-metric-num { font-family: 'Playfair Display', serif; font-size: 36px; font-weight: 700; color: var(--primary); line-height: 1; margin-bottom: 8px; }
.p-metric-label { font-size: 13px; color: var(--muted); line-height: 1.4; }

/* ===== FOOTER ===== */
.site-footer { background: var(--navy); padding: 72px 0 0; }
.footer-top {
  display: grid;
  grid-template-columns: 280px 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 56px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-tagline { font-size: 14px; color: rgba(255,255,255,0.55); line-height: 1.6; margin-bottom: 24px; max-width: 220px; }
.footer-social { display: flex; gap: 12px; }
.social-link {
  width: 36px; height: 36px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: rgba(255,255,255,0.7);
  transition: border-color 0.15s, color 0.15s;
}
.social-link:hover { border-color: var(--gold); color: var(--gold); }
.footer-nav-col h4 {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-nav-col ul { list-style: none; }
.footer-nav-col li { margin-bottom: 10px; }
.footer-nav-col a { font-size: 14px; color: rgba(255,255,255,0.65); transition: color 0.15s; }
.footer-nav-col a:hover { color: #fff; }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 24px 0;
  flex-wrap: wrap;
}
.footer-copy { font-size: 13px; color: rgba(255,255,255,0.4); }
.footer-legal { display: flex; gap: 24px; flex-wrap: wrap; }
.footer-legal a { font-size: 12px; color: rgba(255,255,255,0.4); transition: color 0.15s; }
.footer-legal a:hover { color: rgba(255,255,255,0.8); }

/* ===== SECTION HEADINGS ===== */
.section-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 16px;
}
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(28px, 3vw, 40px);
  font-weight: 700;
  color: var(--navy);
  line-height: 1.25;
  margin-bottom: 16px;
}
.section-subtitle { font-size: 17px; color: var(--muted); margin-bottom: 48px; max-width: 600px; line-height: 1.65; }

/* ===== LINK ARROW ===== */
.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--primary);
  text-decoration: none;
  letter-spacing: 0.3px;
}
.link-arrow::after { content: '→'; transition: transform 0.2s; }
.link-arrow:hover::after { transform: translateX(4px); }

/* ===== CAROUSEL ===== */
.carousel-container { position: relative; overflow: hidden; }
.carousel-track { display: flex; transition: transform 0.4s ease; }
.carousel-slide { flex: 0 0 100%; padding: 40px; background: #fff; border: 1px solid var(--border); }
.carousel-controls { display: flex; justify-content: center; gap: 12px; margin-top: 24px; }
.carousel-btn {
  width: 40px; height: 40px;
  border: 1.5px solid var(--border);
  background: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: var(--navy);
  transition: border-color 0.15s, background 0.15s;
}
.carousel-btn:hover { border-color: var(--primary); background: var(--primary); color: #fff; }

/* ===== PROPERTY TYPES CTA ===== */
.property-types-cta { padding: 72px 0; background: var(--bg-light); }
.property-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-top: 40px;
}
.property-tile {
  background: var(--navy);
  padding: 32px 20px;
  text-align: center;
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.property-tile:hover { background: var(--primary); transform: translateY(-4px); }
.property-tile-icon { font-size: 28px; }
.property-tile-label { font-size: 13px; font-weight: 600; color: #fff; letter-spacing: 0.5px; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .container { padding: 0 24px; }
  .cap-grid { grid-template-columns: repeat(2, 1fr); }
  .related-services-grid { grid-template-columns: repeat(2, 1fr); }
  .ri-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-top { grid-template-columns: 1fr 1fr; gap: 40px; }
  .intro-inner { grid-template-columns: 1fr; gap: 40px; }
  .partnership-inner { grid-template-columns: 1fr; gap: 48px; }
  .topics-layout { grid-template-columns: 1fr; }
  .property-grid { grid-template-columns: repeat(3, 1fr); }
  .mega-menu { width: 700px; }
}
@media (max-width: 768px) {
  .container { padding: 0 20px; }
  .main-nav { display: none; }
  .header-actions { display: none; }
  .hamburger { display: flex; }
  .mobile-menu { display: block; }
  .mega-menu { display: none; }
  .cap-grid { grid-template-columns: 1fr; }
  .related-services-grid { grid-template-columns: 1fr; }
  .ri-grid { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .partnership-metrics { grid-template-columns: 1fr; }
  .property-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .footer-top { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; gap: 16px; }
  .footer-legal { gap: 12px; }
  .property-grid { grid-template-columns: 1fr 1fr; }
}

raw_arguments.content:
/* ===== GLOBALSTONE — SHARED STYLES ===== */

:root {
  --primary: #003F2D;
  --secondary: #012A2D;
  --navy: #0A1628;
  --gold: #C9A84C;
  --light: #E6E6E6;
  --border: #e2e4e8;
  --muted: #5a6474;
  --bg-light: #f7f8f9;
  --white: #ffffff;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--navy);
  background: #fff;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font-family: inherit; }

.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 40px;
}

/* ===== HEADER ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--navy);
  border-bottom: 1px solid rgba(255,255,255,0.08);
  transition: box-shadow 0.3s;
}
.site-header.scrolled {
  box-shadow: 0 4px 24px rgba(0,0,0,0.25);
}
.header-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 0;
}

/* LOGO */
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
  margin-right: 40px;
}
.logo-mark {
  width: 36px; height: 36px;
  background: var(--gold);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 13px;
  color: #0A1628;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}
.logo-text {
  font-size: 18px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.3px;
}

/* MAIN NAV */
.main-nav { flex: 1; }
.nav-list { display: flex; align-items: center; height: 72px; gap: 0; }
.nav-item { position: relative; height: 100%; }
.nav-link {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 100%;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 500;
  color: rgba(255,255,255,0.85);
  text-decoration: none;
  background: none;
  border: none;
  cursor: pointer;
  transition: color 0.18s;
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active { color: #fff; }
.nav-item.has-mega .nav-link:hover { color: var(--gold); }
.nav-chevron { font-size: 12px; transition: transform 0.2s; }
.nav-item.has-mega.open .nav-chevron { transform: rotate(180deg); }

/* HEADER ACTIONS */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-left: 20px;
  flex-shrink: 0;
}
.btn-header-search {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px; height: 36px;
  color: rgba(255,255,255,0.7);
  transition: color 0.18s;
}
.btn-header-search:hover { color: #fff; }
.btn-contact {
  padding: 8px 20px;
  background: var(--gold);
  color: #0A1628;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.3px;
  border-radius: 2px;
  transition: background 0.18s;
}
.btn-contact:hover { background: #d4a017; }

/* HAMBURGER */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 36px; height: 36px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  margin-left: 12px;
}
.hamburger span {
  display: block;
  height: 2px;
  background: rgba(255,255,255,0.85);
  border-radius: 1px;
  transition: all 0.25s;
}
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* MEGA MENU */
.mega-menu {
  position: absolute;
  top: 72px;
  left: 50%;
  transform: translateX(-50%);
  width: 860px;
  background: #fff;
  border-top: 3px solid var(--gold);
  box-shadow: 0 16px 48px rgba(0,0,0,0.18);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.2s, visibility 0.2s, transform 0.2s;
  transform: translateX(-50%) translateY(-8px);
  z-index: 999;
}
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}
.mega-inner {
  display: grid;
  grid-template-columns: 1fr 1fr 240px;
  gap: 0;
  padding: 40px;
}
.mega-col { padding: 0 24px; }
.mega-col:first-child { padding-left: 0; }
.mega-col.mega-featured { border-left: 1px solid var(--border); }
.mega-heading {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border);
}
.mega-list { list-style: none; }
.mega-list li { margin-bottom: 2px; }
.mega-list a {
  display: block;
  padding: 8px 0;
  font-size: 14px;
  font-weight: 500;
  color: var(--navy);
  transition: color 0.15s, padding-left 0.15s;
}
.mega-list a:hover { color: var(--primary); padding-left: 6px; }
.mega-feature-card { margin-top: 8px; }
.mega-feature-img {
  height: 100px;
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  border-radius: 2px;
  margin-bottom: 14px;
}
.mega-feature-tag { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 6px; }
.mega-feature-title { font-size: 13px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 14px; }

/* MOBILE MENU */
.mobile-menu {
  display: none;
  background: var(--navy);
  border-top: 1px solid rgba(255,255,255,0.08);
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.mobile-menu.open {
  max-height: 600px;
  overflow-y: auto;
}
.mobile-nav-list { padding: 16px 0 24px; }
.mobile-nav-item { border-bottom: 1px solid rgba(255,255,255,0.06); }
.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 40px;
  font-size: 15px;
  font-weight: 500;
  color: rgba(255,255,255,0.9);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: color 0.18s;
}
.mobile-nav-link:hover { color: var(--gold); }
.accordion-icon { font-size: 20px; color: var(--gold); transition: transform 0.25s; }
.mobile-nav-item.open .accordion-icon { transform: rotate(45deg); }
.accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}
.accordion-panel.open { max-height: 600px; }
.accordion-sub {
  padding: 8px 40px 20px 56px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.accordion-sub-heading {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--gold);
  margin: 12px 0 8px;
}
.accordion-sub a {
  font-size: 14px;
  color: rgba(255,255,255,0.75);
  padding: 6px 0;
  transition: color 0.15s;
}
.accordion-sub a:hover { color: #fff; }

/* ===== PAGE HERO (non-home pages) ===== */
.page-hero {
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 50%, var(--navy) 100%);
  padding: 80px 0 72px;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute; inset: 0;
  background: url('https://images.unsplash.com/photo-1486325212027-8081e485255e?w=1600&q=60') center/cover;
  opacity: 0.1;
}
.page-hero-content { position: relative; z-index: 2; max-width: 760px; }
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  margin-bottom: 20px;
}
.breadcrumb a { color: rgba(255,255,255,0.6); }
.breadcrumb a:hover { color: rgba(255,255,255,0.9); }
.breadcrumb-sep { font-size: 10px; }
.page-hero-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: var(--gold); margin-bottom: 16px; }
.page-hero-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(32px, 4vw, 52px);
  font-weight: 700;
  color: #fff;
  line-height: 1.2;
  margin-bottom: 20px;
}
.page-hero-desc { font-size: 17px; color: rgba(255,255,255,0.8); line-height: 1.65; max-width: 600px; }

/* ===== INTRO STATEMENT ===== */
.intro-statement {
  padding: 72px 0;
  background: #fff;
  border-bottom: 1px solid var(--border);
}
.intro-inner {
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 80px;
  align-items: center;
}
.intro-text h2 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(26px, 2.5vw, 36px);
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 18px;
  line-height: 1.3;
}
.intro-text p { font-size: 16px; color: var(--muted); line-height: 1.75; }
.intro-stat-stack { display: flex; flex-direction: column; gap: 24px; }
.intro-stat { border-left: 3px solid var(--gold); padding-left: 20px; }
.intro-stat-num { font-family: 'Playfair Display', serif; font-size: 36px; font-weight: 700; color: var(--primary); line-height: 1; margin-bottom: 4px; }
.intro-stat-label { font-size: 13px; color: var(--muted); font-weight: 500; }

/* ===== CAPABILITIES GRID ===== */
.capabilities-section { padding: 80px 0; background: var(--bg-light); }
.cap-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.cap-card {
  background: #fff;
  padding: 36px 28px;
  border: 1px solid var(--border);
  border-top: 3px solid var(--primary);
  transition: box-shadow 0.2s, transform 0.2s;
}
.cap-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.09); transform: translateY(-3px); }
.cap-icon {
  width: 44px; height: 44px;
  background: rgba(0,63,45,0.1);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 18px;
}
.cap-card h3 { font-size: 17px; font-weight: 700; color: var(--navy); margin-bottom: 12px; line-height: 1.3; }
.cap-card p { font-size: 14px; color: var(--muted); line-height: 1.7; margin-bottom: 20px; }

/* ===== RELATED SERVICES ===== */
.related-services { padding: 72px 0; background: #fff; }
.related-services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.related-card {
  border: 1px solid var(--border);
  padding: 32px;
  transition: box-shadow 0.2s;
}
.related-card:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.08); }
.related-card h3 { font-size: 16px; font-weight: 700; color: var(--navy); margin-bottom: 10px; }
.related-card p { font-size: 14px; color: var(--muted); line-height: 1.65; margin-bottom: 20px; }

/* ===== TESTIMONIAL ===== */
.testimonial-section { padding: 80px 0; background: var(--navy); }
.testimonial-inner { max-width: 760px; margin: 0 auto; text-align: center; }
.testimonial-quote {
  font-family: 'Playfair Display', serif;
  font-size: clamp(22px, 2.5vw, 30px);
  font-weight: 400;
  color: #fff;
  line-height: 1.55;
  margin-bottom: 32px;
  font-style: italic;
}
.testimonial-quote::before { content: '"'; }
.testimonial-quote::after { content: '"'; }
.testimonial-author { font-size: 14px; font-weight: 600; color: var(--gold); letter-spacing: 0.5px; margin-bottom: 4px; }
.testimonial-role { font-size: 13px; color: rgba(255,255,255,0.6); }

/* ===== CTA SECTION ===== */
.cta-section { padding: 80px 0; background: var(--primary); }
.cta-inner { text-align: center; }
.cta-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(28px, 3vw, 40px);
  font-weight: 700;
  color: #fff;
  margin-bottom: 16px;
}
.cta-subtitle { font-size: 17px; color: rgba(255,255,255,0.8); margin-bottom: 36px; }
.btn-cta-white {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #fff;
  color: var(--primary);
  font-weight: 700;
  font-size: 15px;
  padding: 15px 36px;
  border: none;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.2s, transform 0.2s;
}
.btn-cta-white:hover { background: #f0f0f0; transform: translateY(-2px); }

/* ===== FEATURED TOPICS ===== */
.featured-topics { padding: 72px 0; background: #fff; }
.topics-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 64px;
  align-items: start;
  margin-top: 40px;
}
.topics-list { border: 1px solid var(--border); }
.topic-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 28px;
  border-bottom: 1px solid var(--border);
  transition: background 0.15s;
  cursor: pointer;
}
.topic-item:last-child { border-bottom: none; }
.topic-item:hover { background: var(--bg-light); }
.topic-item h3 { font-size: 16px; font-weight: 600; color: var(--navy); }
.topic-item span { color: var(--gold); font-size: 20px; }
.insight-sidebar { display: flex; flex-direction: column; gap: 24px; }
.sidebar-card {
  border: 1px solid var(--border);
  overflow: hidden;
}
.sidebar-card-img { height: 140px; background: linear-gradient(135deg, var(--primary), var(--secondary)); overflow: hidden; }
.sidebar-card-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.7; }
.sidebar-card-body { padding: 20px; }
.sidebar-card-tag { font-size: 10px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 8px; }
.sidebar-card-body h3 { font-size: 14px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 12px; }

/* ===== RELATED INSIGHTS ===== */
.related-insights { padding: 72px 0; background: var(--bg-light); }
.ri-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.ri-card {
  background: #fff;
  border: 1px solid var(--border);
  overflow: hidden;
  transition: box-shadow 0.2s;
}
.ri-card:hover { box-shadow: 0 6px 24px rgba(0,0,0,0.09); }
.ri-card-img { height: 160px; background: linear-gradient(135deg, var(--primary), var(--secondary)); overflow: hidden; }
.ri-card-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.65; }
.ri-card-body { padding: 24px; }
.ri-tag { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 8px; }
.ri-card-body h3 { font-size: 15px; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 14px; }
.ri-date { font-size: 12px; color: var(--muted); }

/* ===== PARTNERSHIP HIGHLIGHT ===== */
.partnership { padding: 80px 0; background: #fff; }
.partnership-inner {
  display: grid;
  grid-template-columns: 1fr 400px;
  gap: 72px;
  align-items: center;
}
.partnership-text h2 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(26px, 2.5vw, 36px);
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 20px;
  line-height: 1.3;
}
.partnership-text p { font-size: 16px; color: var(--muted); line-height: 1.75; margin-bottom: 24px; }
.partnership-metrics { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.p-metric { background: var(--bg-light); padding: 28px 24px; border-left: 3px solid var(--gold); }
.p-metric-num { font-family: 'Playfair Display', serif; font-size: 36px; font-weight: 700; color: var(--primary); line-height: 1; margin-bottom: 8px; }
.p-metric-label { font-size: 13px; color: var(--muted); line-height: 1.4; }

/* ===== FOOTER ===== */
.site-footer { background: var(--navy); padding: 72px 0 0; }
.footer-top {
  display: grid;
  grid-template-columns: 280px 1fr 1fr 1fr;
  gap: 48px;
  padding-bottom: 56px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-tagline { font-size: 14px; color: rgba(255,255,255,0.55); line-height: 1.6; margin-bottom: 24px; max-width: 220px; }
.footer-social { display: flex; gap: 12px; }
.social-link {
  width: 36px; height: 36px;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: rgba(255,255,255,0.7);
  transition: border-color 0.15s, color 0.15s;
}
.social-link:hover { border-color: var(--gold); color: var(--gold); }
.footer-nav-col h4 {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-nav-col ul { list-style: none; }
.footer-nav-col li { margin-bottom: 10px; }
.footer-nav-col a { font-size: 14px; color: rgba(255,255,255,0.65); transition: color 0.15s; }
.footer-nav-col a:hover { color: #fff; }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 24px 0;
  flex-wrap: wrap;
}
.footer-copy { font-size: 13px; color: rgba(255,255,255,0.4); }
.footer-legal { display: flex; gap: 24px; flex-wrap: wrap; }
.footer-legal a { font-size: 12px; color: rgba(255,255,255,0.4); transition: color 0.15s; }
.footer-legal a:hover { color: rgba(255,255,255,0.8); }

/* ===== SECTION HEADINGS ===== */
.section-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 16px;
}
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(28px, 3vw, 40px);
  font-weight: 700;
  color: var(--navy);
  line-height: 1.25;
  margin-bottom: 16px;
}
.section-subtitle { font-size: 17px; color: var(--muted); margin-bottom: 48px; max-width: 600px; line-height: 1.65; }

/* ===== LINK ARROW ===== */
.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--primary);
  text-decoration: none;
  letter-spacing: 0.3px;
}
.link-arrow::after { content: '→'; transition: transform 0.2s; }
.link-arrow:hover::after { transform: translateX(4px); }

/* ===== CAROUSEL ===== */
.carousel-container { position: relative; overflow: hidden; }
.carousel-track { display: flex; transition: transform 0.4s ease; }
.carousel-slide { flex: 0 0 100%; padding: 40px; background: #fff; border: 1px solid var(--border); }
.carousel-controls { display: flex; justify-content: center; gap: 12px; margin-top: 24px; }
.carousel-btn {
  width: 40px; height: 40px;
  border: 1.5px solid var(--border);
  background: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: var(--navy);
  transition: border-color 0.15s, background 0.15s;
}
.carousel-btn:hover { border-color: var(--primary); background: var(--primary); color: #fff; }

/* ===== PROPERTY TYPES CTA ===== */
.property-types-cta { padding: 72px 0; background: var(--bg-light); }
.property-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-top: 40px;
}
.property-tile {
  background: var(--navy);
  padding: 32px 20px;
  text-align: center;
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.property-tile:hover { background: var(--primary); transform: translateY(-4px); }
.property-tile-icon { font-size: 28px; }
.property-tile-label { font-size: 13px; font-weight: 600; color: #fff; letter-spacing: 0.5px; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .container { padding: 0 24px; }
  .cap-grid { grid-template-columns: repeat(2, 1fr); }
  .related-services-grid { grid-template-columns: repeat(2, 1fr); }
  .ri-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-top { grid-template-columns: 1fr 1fr; gap: 40px; }
  .intro-inner { grid-template-columns: 1fr; gap: 40px; }
  .partnership-inner { grid-template-columns: 1fr; gap: 48px; }
  .topics-layout { grid-template-columns: 1fr; }
  .property-grid { grid-template-columns: repeat(3, 1fr); }
  .mega-menu { width: 700px; }
}
@media (max-width: 768px) {
  .container { padding: 0 20px; }
  .main-nav { display: none; }
  .header-actions { display: none; }
  .hamburger { display: flex; }
  .mobile-menu { display: block; }
  .mega-menu { display: none; }
  .cap-grid { grid-template-columns: 1fr; }
  .related-services-grid { grid-template-columns: 1fr; }
  .ri-grid { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .partnership-metrics { grid-template-columns: 1fr; }
  .property-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .footer-top { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; gap: 16px; }
  .footer-legal { gap: 12px; }
  .property-grid { grid-template-columns: 1fr 1fr; }
}

